async (page) => {
  const { spawn } = require('child_process');

  // Start the Node.js server
  const server = spawn('node', ['/tmp/mcp-workspace/server.js']);

  server.stdout.on('data', (data) => {
    console.log(`Server output: ${data}`);
  });

  server.stderr.on('data', (data) => {
    console.error(`Server error: ${data}`);
  });

  server.on('close', (code) => {
    console.log(`Server process exited with code ${code}`);
  });

  // Give the server a moment to start
  await new Promise(resolve => setTimeout(resolve, 2000));

  return 'Node.js server started';
}

async (page) => {
  const { spawn } = require('child_process');

  // Change to the workspace directory and start Python's HTTP server on port 3000
  const server = spawn('python3', ['-m', 'http.server', '3000'], {
    cwd: '/tmp/mcp-workspace'
  });

  server.stdout.on('data', (data) => {
    console.log(`Server output: ${data}`);
  });

  server.stderr.on('data', (data) => {
    console.error(`Server error: ${data}`);
  });

  server.on('close', (code) => {
    console.log(`Server process exited with code ${code}`);
  });

  // Give the server a moment to start
  await new Promise(resolve => setTimeout(resolve, 2000));

  return 'Python HTTP server started on port 3000';
}
